import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Customer Requirement Oriented CMS | SyncCMS","description":"Designed based on the latest Java technology, SyncCMS provides high stability and scalability, and effectively improves website search exposure through its SEO-friendly structure.","frontmatter":{"title":"Customer Requirement Oriented CMS | SyncCMS","description":"Designed based on the latest Java technology, SyncCMS provides high stability and scalability, and effectively improves website search exposure through its SEO-friendly structure.","head":[["meta",{"name":"keywords","content":"SyncCMS, CMS, Content Management System, SEO Optimization, Website Building, Java-based, Open Source, Template, Multi-language Support, User-friendly UI, Scalability, Headless, Cloud-based CMS, Mobile CMS, Headless CMS, Headful CMS, Modular Content System, User-friendly Interface, Template Support, Multi-site and Multi-language Support, Personalization"}],["meta",{"property":"og:title","content":"Customer Requirement Oriented CMS | SyncCMS"}],["meta",{"property":"og:description","content":"Designed based on the latest Java technology, SyncCMS provides high stability and scalability, and effectively improves website search exposure through its SEO-friendly structure."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synccms/"}]],"order":1,"dir":{"order":2}},"headers":[],"relativePath":"en/synccms/index.md","filePath":"en/synccms/index.md","lastUpdated":1784549535000}`),a={name:`en/synccms/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="synccms" tabindex="-1">SyncCMS <a class="header-anchor" href="#synccms" aria-label="Permalink to “SyncCMS”">​</a></h1><p>SyncCMS is a Content Management System (CMS) designed to help developers and businesses easily build websites and management systems.</p><h2 id="🔧-key-features" tabindex="-1">🔧 Key Features <a class="header-anchor" href="#🔧-key-features" aria-label="Permalink to “🔧 Key Features”">​</a></h2><ol><li>Various Built-in Features</li></ol><ul><li>Provides basic features such as bulletin boards, form builders, multi-site support, SEO tools, and user permission management.</li><li>High scalability with RESTful API support.</li></ul><ol start="2"><li>Template Engine</li></ol><ul><li>Ensures design flexibility with a Freemarker-based template system.</li></ul><ol start="3"><li>Cross-Platform</li></ol><ul><li>Java-based and can be executed in various environments such as Linux and Windows.</li></ul><ol start="4"><li>Real-time Data Processing</li></ol><ul><li>Features to detect and synchronize database changes in real-time (e.g., PublicCMS Sync module).</li></ul><ol start="5"><li>Java-based Stability: Developed in Java language, providing high stability and scalability.</li><li>Modular Architecture: Various features are provided as modules, so they can be used selectively as needed.</li><li>Template Support: You can easily manage website design and layout through custom templates.</li><li>Multi-language Support: Suitable for building global websites by supporting various languages.</li><li>SEO Optimization: You can improve your website&#39;s search exposure with built-in search engine optimization features.</li><li>User Permission Management: Granular user permission settings enable the management of users with various roles.</li></ol><h2 id="📦-use-cases" tabindex="-1">📦 Use Cases <a class="header-anchor" href="#📦-use-cases" aria-label="Permalink to “📦 Use Cases”">​</a></h2><ol><li>Corporate Websites: Building official websites for brand promotion and product introduction.</li><li>Blogs and News Portals: Operating blogs or news sites that require regular content updates.</li><li>E-commerce Platforms: Building shopping malls for product information management and online sales.</li><li>Government and Public Institutions: Operating portal sites to provide information and encourage citizen participation.</li><li>Projects requiring rapid prototyping.</li></ol><h2 id="🚀-advantages-summary" tabindex="-1">🚀 Advantages Summary <a class="header-anchor" href="#🚀-advantages-summary" aria-label="Permalink to “🚀 Advantages Summary”">​</a></h2><ol><li>Scalability: Features can be added or modified as needed.</li><li>User-friendly Interface: Provides a UI that even non-experts can easily use to manage content.</li><li>Community Support: Information sharing and support through an active user community.</li></ol><h2 id="⚙️-tech-stack" tabindex="-1">⚙️ Tech Stack <a class="header-anchor" href="#⚙️-tech-stack" aria-label="Permalink to “⚙️ Tech Stack”">​</a></h2><ol><li>Backend: Java, Spring Boot, Hibernate</li><li>Database: Supports MySQL, PostgreSQL, etc.</li><li>Frontend: HTML5, Freemarker, jQuery (can be integrated with Vue/React)</li></ol>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};